// This automatically gets the "homepage" value from package.json
const BASE_URL = process.env.PUBLIC_URL || "";

// Helper to format image paths
const getImagePath = (path) => {
  if (!path) return "";
  // If the path already starts with http, return it as is
  if (path.startsWith("http")) return path;
  // Otherwise, ensure it starts with a slash and prepend the base URL
  const cleanPath = path.startsWith("/") ? path : `/${path}`;
  return `${BASE_URL}${cleanPath}`;
};

