const CatalogueEditor = ({ catalogue, setCatalogue }) => {
  const [activeSubTab, setActiveSubTab] = useState("models");

  // Helper to update deeply nested prices
  const updatePrice = (path, value) => {
    const updated = JSON.parse(JSON.stringify(catalogue));
    let current = updated;
    for (let i = 0; i < path.length - 1; i++) {
      current = current[path[i]];
    }
    current[path[path.length - 1]] = parseFloat(value) || 0;
    setCatalogue(updated);
  };

  const TabButton = ({ id, label, icon: Icon }) => (
    <button
      onClick={() => setActiveSubTab(id)}
      className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-bold transition-all ${
        activeSubTab === id
          ? "bg-blue-600 text-white"
          : "text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-700"
      }`}
    >
      <Icon size={16} /> {label}
    </button>
  );

  return (
    <div className="space-y-6">
      <div className="flex gap-2 border-b dark:border-slate-700 pb-3">
        <TabButton id="models" label="Models & Lines" icon={Database} />
        <TabButton id="accessories" label="Accessories" icon={Package} />
        <TabButton id="services" label="Services" icon={ToolCase} />
      </div>

      <div className="max-h-[50vh] overflow-y-auto pr-2 space-y-8">
        {/* Models Section */}
        {activeSubTab === "models" &&
          catalogue.manufacturer[0].lines.map((line, lIdx) => (
            <div key={line.id} className="space-y-3">
              <h4 className="font-bold text-blue-600 border-l-4 border-blue-600 pl-2 uppercase text-xs tracking-widest">
                {line.name} Series
              </h4>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                {line.models.map((model, mIdx) => (
                  <div
                    key={model.id}
                    className="flex items-center justify-between p-3 bg-slate-50 dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-700"
                  >
                    <span className="font-medium text-sm">{model.name}</span>
                    <div className="flex items-center gap-2">
                      <span className="text-xs text-slate-400">$</span>
                      <input
                        type="number"
                        value={model.price}
                        onChange={(e) =>
                          updatePrice(
                            [
                              "manufacturer",
                              0,
                              "lines",
                              lIdx,
                              "models",
                              mIdx,
                              "price",
                            ],
                            e.target.value
                          )
                        }
                        className="w-24 p-1 rounded border dark:bg-slate-800 dark:border-slate-600 text-right text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                      />
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ))}

        {/* Accessories Section */}
        {activeSubTab === "accessories" &&
          catalogue.accessories.map((category, cIdx) => (
            <div key={category.id} className="space-y-3">
              <h4 className="font-bold text-blue-600 border-l-4 border-blue-600 pl-2 uppercase text-xs tracking-widest">
                {category.name}
              </h4>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                {category.products.map((item, pIdx) => (
                  <div
                    key={item.id || pIdx}
                    className="flex items-center justify-between p-3 bg-slate-50 dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-700"
                  >
                    <span className="font-medium text-sm truncate max-w-[150px]">
                      {item.name}
                    </span>
                    <div className="flex items-center gap-2">
                      <span className="text-xs text-slate-400">$</span>
                      <input
                        type="number"
                        value={item.price}
                        onChange={(e) =>
                          updatePrice(
                            ["accessories", cIdx, "products", pIdx, "price"],
                            e.target.value
                          )
                        }
                        className="w-24 p-1 rounded border dark:bg-slate-800 dark:border-slate-600 text-right text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                      />
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ))}
        {/* Services logic follows same pattern */}
        {activeSubTab === "services" &&
          catalogue.services.map((category, cIdx) => (
            <div key={category.id} className="space-y-3">
              <h4 className="font-bold text-blue-600 border-l-4 border-blue-600 pl-2 uppercase text-xs tracking-widest">
                {category.name}
              </h4>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                {category.products.map((item, pIdx) => (
                  <div
                    key={item.id || pIdx}
                    className="flex items-center justify-between p-3 bg-slate-50 dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-700"
                  >
                    <span className="font-medium text-sm truncate max-w-[150px]">
                      {item.name}
                    </span>
                    <div className="flex items-center gap-2">
                      <span className="text-xs text-slate-400">$</span>
                      <input
                        type="number"
                        value={item.price}
                        onChange={(e) =>
                          updatePrice(
                            ["services", cIdx, "products", pIdx, "price"],
                            e.target.value
                          )
                        }
                        className="w-24 p-1 rounded border dark:bg-slate-800 dark:border-slate-600 text-right text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                      />
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ))}
      </div>
    </div>
  );
};

const PromotionEditor = ({ promotions, setPromotions }) => {
  const togglePromo = (id) => {
    const updated = {
      ...promotions,
      promotions: promotions.promotions.map((p) =>
        p.id === id ? { ...p, isActive: !p.isActive } : p
      ),
    };
    setPromotions(updated);
    localStorage.setItem("spa_promotions", JSON.stringify(updated));
  };
  return (
    <div className="space-y-4">
      <div className="flex justify-between items-center">
        <h3 className="font-bold text-lg">Manage Active Promotions</h3>
        <button className="bg-green-600 text-white px-3 py-1 rounded text-sm">
          + Add Promo
        </button>
      </div>
      {promotions.promotions.map((promo) => (
        <div
          key={promo.id}
          className="flex items-center justify-between p-3 border rounded-lg dark:border-slate-600"
        >
          <div>
            <p className="font-semibold">{promo.name}</p>
            <p className="text-xs text-slate-500">
              {promo.discountType === "percentage"
                ? `${promo.amount}% off`
                : `$${promo.amount} off`}
            </p>
          </div>
          <button
            onClick={() => togglePromo(promo.id)}
            className={`px-3 py-1 rounded text-xs font-bold ${
              promo.isActive
                ? "bg-green-100 text-green-700"
                : "bg-red-100 text-red-700"
            }`}
          >
            {promo.isActive ? "ACTIVE" : "INACTIVE"}
          </button>
        </div>
      ))}
    </div>
  );
};

const steps = [
  "Select Line",
  "Select Model",
  "Configure Colors",
  "Accessories",
  "Summary",
  "Payment and Delivery",
];

const StepWizard = ({ currentStep }) => (
  <div className="flex justify-between items-center mb-8 px-4 py-4 bg-blue-900 rounded-lg shadow-lg">
    {steps.map((step, idx) => {
      const isActive = idx === currentStep;
      const isCompleted = idx < currentStep;

      return (
        <div key={idx} className="flex flex-col items-center flex-1 relative">
          <div
            className={`w-8 h-8 rounded-full flex items-center justify-center font-bold text-sm z-10 transition-colors duration-300 
              ${
                isActive
                  ? "bg-orange-500 text-white"
                  : isCompleted
                  ? "bg-blue-600 text-white"
                  : "bg-blue-800 text-blue-400"
              }`}
          >
            {isCompleted ? <Check size={16} /> : idx + 1}
          </div>
          <span
            className={`text-xs mt-2 font-medium hidden sm:block ${
              isActive ? "text-white" : "text-blue-300"
            }`}
          >
            {step}
          </span>
          {idx !== steps.length - 1 && (
            <div className="absolute top-4 left-1/2 w-full h-[2px] bg-blue-800 -z-0">
              <div
                className="h-full bg-blue-600 transition-all duration-300"
                style={{ width: isCompleted ? "100%" : "0%" }}
              ></div>
            </div>
          )}
        </div>
      );
    })}
  </div>
);

