const Step3Configuration = ({
  model,
  line,
  configuration,
  setConfiguration,
  setCurrentStep,
}) => {
  if (!model || !line) return null;

  // Helper: Check if a combination exists in the map
  const isValidCombo = (sId, cId) => !!model.image_map[`${sId}-${cId}`];

  const handleShellSelect = (newShellId) => {
    // If the current cabinet isn't valid for the new shell, pick the first valid one automatically
    if (!isValidCombo(newShellId, configuration.cabinet)) {
      const firstValidCabinet = line.options.cabinets.find((c) =>
        isValidCombo(newShellId, c.id)
      );
      if (firstValidCabinet) {
        setConfiguration({
          shell: newShellId,
          cabinet: firstValidCabinet.id,
        });
        return;
      }
    }
    setConfiguration((prev) => ({ ...prev, shell: newShellId }));
  };

  // Determine current image from map
  const imageKey = `${configuration.shell}-${configuration.cabinet}`;
  const previewImage =
    getImagePath(model.image_map[imageKey]) || getImagePath(model.img);

  return (
    <div className="flex flex-col lg:flex-row gap-8 animate-in fade-in duration-500">
      {/* Visualizer */}
      <div className="lg:w-2/3 bg-white rounded-2xl shadow-lg p-6 flex items-center justify-center min-h-[400px] relative">
        <img
          src={previewImage}
          alt={`${model.name} Preview`}
          className="max-w-full max-h-[60vh] object-contain transition-opacity duration-300"
        />
        <div className="absolute top-4 left-4 bg-white/80 backdrop-blur px-4 py-2 rounded-lg text-sm text-gray-500">
          {model.name} Preview
        </div>
      </div>

      {/* Options Panel */}
      <div className="lg:w-1/3 space-y-8 bg-slate-50 p-6 rounded-2xl border border-slate-200">
        <div>
          <h3 className="text-lg font-bold text-slate-900 mb-4 flex items-center gap-2">
            1. Select Shell
          </h3>
          <div className="grid grid-cols-3 gap-3">
            {line.options.shells.map((shell) => {
              // A shell is valid if it has AT LEAST one valid cabinet option
              const hasValidCabinet = line.options.cabinets.some((c) =>
                isValidCombo(shell.id, c.id)
              );

              if (!hasValidCabinet) return null; // Don't show shells that have no possible cabinets for this model

              return (
                <button
                  key={shell.id}
                  onClick={() => handleShellSelect(shell.id)}
                  className={`relative rounded-xl overflow-hidden border-2 transition-all p-1 bg-white
                       ${
                         configuration.shell === shell.id
                           ? "border-orange-500 ring-2 ring-orange-500/20"
                           : "border-gray-200 hover:border-blue-300"
                       }`}
                >
                  <img
                    src={shell.img}
                    alt={shell.name}
                    className="w-full h-16 object-cover rounded-lg"
                  />
                  <span className="block text-xs font-medium text-center mt-1 text-gray-700 truncate px-1">
                    {shell.name}
                  </span>
                </button>
              );
            })}
          </div>
        </div>

        <div className="w-full h-px bg-gray-200"></div>

        <div>
          <h3 className="text-lg font-bold text-slate-900 mb-4 flex items-center gap-2">
            2. Select Cabinet
          </h3>
          <div className="grid grid-cols-3 gap-3">
            {line.options.cabinets.map((cab) => {
              // Check if valid for currently selected shell
              const isValid = isValidCombo(configuration.shell, cab.id);

              return (
                <button
                  key={cab.id}
                  onClick={() =>
                    isValid &&
                    setConfiguration((prev) => ({ ...prev, cabinet: cab.id }))
                  }
                  disabled={!isValid}
                  className={`relative rounded-xl overflow-hidden border-2 transition-all p-1 
                       ${
                         !isValid
                           ? "bg-gray-100 opacity-40 cursor-not-allowed border-gray-100"
                           : "bg-white"
                       }
                       ${
                         isValid && configuration.cabinet === cab.id
                           ? "border-orange-500 ring-2 ring-orange-500/20"
                           : "border-gray-200 hover:border-blue-300"
                       }`}
                >
                  <img
                    src={cab.img}
                    alt={cab.name}
                    className="w-full h-16 object-cover rounded-lg"
                  />
                  <span className="block text-xs font-medium text-center mt-1 text-gray-700 truncate px-1">
                    {cab.name}
                  </span>
                </button>
              );
            })}
          </div>
        </div>

        <button
          onClick={() => setCurrentStep(3)}
          className="w-full py-4 bg-blue-600 hover:bg-blue-700 text-white rounded-xl font-bold text-lg shadow-lg hover:shadow-xl transition-all flex items-center justify-center gap-2 mt-8"
        >
          Continue to Accessories <ChevronRight />
        </button>
      </div>
    </div>
  );
};

const Step4Accessories = ({
  categorizedAccessories,
  selectedAccessories,
  toggleAccessory,
  selectedModel,
  setCurrentStep,
  getImagePath,
}) => {
  return (
    <div className="space-y-12 pb-32 animate-in fade-in slide-in-from-right-8 duration-500">
      <div className="mb-8">
        <h2 className="text-3xl font-bold text-blue-900">
          Enhance Your Experience
        </h2>
        <p className="text-slate-500 mt-2">
          Select the accessories and features you'd like to add to your{" "}
          {selectedModel?.name}.
        </p>
      </div>

      {Object.entries(categorizedAccessories).map(([categoryName, group]) => {
        const { limit, items } = group;

        // Logic to calculate selection status for this category
        const selectedInCategory = items.filter((item) =>
          selectedAccessories.has(item.id)
        );
        const isAtLimit = limit && selectedInCategory.length >= limit;

        return (
          <div
            key={categoryName}
            className="bg-white rounded-2xl p-6 shadow-sm border border-slate-200"
          >
            {/* Category Header with Limit Counter */}
            <div className="flex flex-col sm:flex-row sm:items-center justify-between mb-6 gap-2 border-b border-slate-100 pb-4">
              <div className="flex items-center gap-3">
                <div className="p-2 bg-blue-50 rounded-lg text-blue-600">
                  <Package size={24} />
                </div>
                <h3 className="text-xl font-bold text-slate-800">
                  {categoryName}
                </h3>
              </div>

              {limit && (
                <div
                  className={`px-4 py-1 rounded-full text-sm font-bold flex items-center gap-2 ${
                    isAtLimit
                      ? "bg-blue-600 text-white"
                      : "bg-slate-100 text-slate-600"
                  }`}
                >
                  {isAtLimit ? (
                    <>
                      <Check size={14} /> Selection Limit Reached
                    </>
                  ) : (
                    `Select up to ${limit} (${selectedInCategory.length}/${limit})`
                  )}
                </div>
              )}
            </div>

            {/* Accessory Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {items.map((acc) => {
                const isSelected = selectedAccessories.has(acc.id);
                // Check if this accessory is already included for free with this specific model
                const isIncluded =
                  selectedModel?.included_accessories?.includes(acc.id);

                // An item is "Disabled" if the limit is reached, it's not currently selected,
                // and it's not one of the mandatory included items.
                const isDisabled = isAtLimit && !isSelected && !isIncluded;

                return (
                  <button
                    key={acc.id}
                    disabled={isDisabled || isIncluded}
                    onClick={() => toggleAccessory(acc.id)}
                    className={`group relative flex flex-col overflow-hidden rounded-xl border-2 transition-all text-left h-full
                      ${
                        isSelected
                          ? "border-blue-600 bg-blue-50/30 ring-2 ring-blue-600/10"
                          : "border-slate-100 bg-white"
                      }
                      ${
                        isIncluded
                          ? "border-green-500 bg-green-50/50 cursor-default"
                          : ""
                      }
                      ${
                        isDisabled
                          ? "opacity-40 cursor-not-allowed grayscale-[0.5]"
                          : "hover:border-blue-300 hover:shadow-md"
                      }
                    `}
                  >
                    {/* Visual "Selected" or "Included" indicators */}
                    <div className="absolute top-3 right-3 z-10">
                      {isIncluded ? (
                        <span className="bg-green-500 text-white text-[10px] font-black px-2 py-1 rounded uppercase tracking-wider">
                          Included
                        </span>
                      ) : isSelected ? (
                        <div className="bg-blue-600 text-white p-1 rounded-full shadow-lg">
                          <Check size={16} />
                        </div>
                      ) : null}
                    </div>

                    {/* Image Section */}
                    <div className="aspect-video bg-slate-50 overflow-hidden border-b border-slate-100">
                      {acc.img ? (
                        <img
                          src={acc.img}
                          alt={acc.name}
                          className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
                        />
                      ) : (
                        <div className="w-full h-full flex items-center justify-center text-slate-300">
                          <Package size={48} />
                        </div>
                      )}
                    </div>

                    {/* Content Section */}
                    <div className="p-4 flex-1 flex flex-col">
                      <h4 className="font-bold text-slate-900 mb-1">
                        {acc.name}
                      </h4>

                      <div className="mt-auto flex items-center justify-between">
                        <span
                          className={`text-lg font-black ${
                            isIncluded ? "text-green-600" : "text-blue-900"
                          }`}
                        >
                          {isIncluded
                            ? "FREE"
                            : acc.price.toLocaleString("en-US", {
                                style: "currency",
                                currency: "USD",
                              })}
                        </span>

                        {!isIncluded && !isDisabled && (
                          <span
                            className={`text-xs font-bold uppercase tracking-widest ${
                              isSelected
                                ? "text-blue-600"
                                : "text-slate-400 group-hover:text-blue-500"
                            }`}
                          >
                            {isSelected ? "Remove" : "Add to Spa"}
                          </span>
                        )}
                      </div>

                      {/* Optional: Show Sales Notes if they exist */}
                      {acc.salesNotes?.length > 0 && (
                        <div className="mt-3 pt-3 border-t border-slate-100 flex items-start gap-2 text-slate-500 italic text-[11px] leading-tight">
                          <Info size={12} className="shrink-0 mt-0.5" />
                          <span>{acc.salesNotes[0]}</span>
                        </div>
                      )}
                    </div>
                  </button>
                );
              })}
            </div>
          </div>
        );
      })}

      {/* Navigation Call to Action */}
      <div className="flex justify-center pt-8">
        <button
          onClick={() => setCurrentStep(4)}
          className="px-12 py-5 bg-blue-900 text-white rounded-2xl font-bold shadow-xl hover:bg-blue-800 hover:-translate-y-1 transition-all flex items-center gap-3"
        >
          Review Your Summary
          <ChevronRight size={20} />
        </button>
      </div>
    </div>
  );
};

